grammar document.provider.TypedTerminalNoDefault hidden(WS)
import "urn:document-provider:paint:no-default:1" as p
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Paint returns p::Paint: 'paint' color=COLOR?;
terminal COLOR returns ecore::EJavaObject: '#' ('0'..'9'|'a'..'f')+;
terminal WS returns ecore::EString: ' '+;

